// Sound effects with plain Web Audio: positional (volume falls off with distance from the
// camera, left/right pan), a little pitch variation so repeats don't sound robotic, and a
// cap on overlapping copies per sound so rapid fire stays clean. Files are generated by
// `pnpm sfx` into public/sfx (see tools/sfx.json). Each animal's voice clips load once a plush
// wearing its head shows up.
import type { Animal, Vec2 } from '@stuffed/sim';

export const SOUNDS = [
  'cork_pop', 'dart_shot', 'soaker_shot',
  'hit_stuffing', 'hit_stuffing_2', 'hit_stuffing_3', 'hit_armor', 'hit_armor_2', 'hit_armor_3', 'hit_confirm', 'ko_confirm', 'impact', 'impact_2', 'splash', 'knockout',
  'chest_rattle', 'chest_open', 'chest_open_low', 'chest_open_high', 'chest_open_food', 'pickup_weapon', 'heal', 'heal_small', 'heal_big', 'juice_done', 'armor_up',
  'use_puff', 'use_sewing', 'use_juice', 'use_bag', 'use_cardboard', 'reload', 'swap',
  'part_head', 'part_body', 'part_legs', 'part_tail', 'part_accessory',
  'grab_buttons', 'grab_stuffing', 'grab_sewing', 'grab_juice', 'grab_cardboard',
  'jump_springy', 'jump_springy_2', 'jump_springy_3', 'jump_heavy', 'jump_heavy_2', 'jump_heavy_3',
  'jump_winged', 'jump_winged_2', 'jump_winged_3', 'jump_squishy', 'jump_squishy_2', 'jump_squishy_3',
  'jump_fluffy', 'jump_fluffy_2', 'jump_fluffy_3',
  'land_springy', 'land_springy_2', 'land_springy_3', 'land_heavy', 'land_heavy_2', 'land_heavy_3',
  'land_winged', 'land_winged_2', 'land_winged_3', 'land_squishy', 'land_squishy_2', 'land_squishy_3',
  'land_fluffy', 'land_fluffy_2', 'land_fluffy_3',
  'step_grass', 'step_grass_2', 'step_wood', 'step_wood_2', 'step_snow', 'step_snow_2', 'step_sand', 'step_sand_2',
  'rinse_rising', 'win', 'lose', 'click',
  'band_twang', 'band_stretch', 'marble_shot', 'marble_bounce', 'marble_burst',
  'pillow_swing', 'pillow_bonk',
  'glitter_throw', 'glitter_burst', 'bubble_blow', 'bubble_pop', 'ball_boing', 'cardboard_place', 'train_toot',
  'strike_whistle', 'balloon_splash', 'block_clatter', 'snow_thud', 'pinata_hit', 'pinata_burst',
  'jack_tune', 'jack_pop', 'sprinkler_spray', 'ice_crack', 'ice_break',
  'slide_whoosh', 'zip_line', 'tube_pop',
  'dig_scrape', 'duck_ding', 'pin_knock', 'prize_fanfare',
  'vacuum_slurp', 'vacuum_bump', 'mower_engine', 'plow_horn', 'ship_bell', 'cannon_fire', 'cannonball_land', 'shark_chomp', 'lava_sizzle',
  'parrot_squawk', 'current_whoosh', 'gull_cry', 'sea_waves', 'waterfall_rush', 'lighthouse_climb', 'shark_warning',
] as const;
export type SoundName = (typeof SOUNDS)[number];
/** `<sound>_<kind>`, `_2` and `_3` for each kind. */
function threeTakes(sound: string, kinds: readonly string[]): Record<string, SoundName[]> {
  return Object.fromEntries(kinds.map((k) => [`${sound}_${k}`, [`${sound}_${k}`, `${sound}_${k}_2`, `${sound}_${k}_3`] as SoundName[]]));
}

/** Sounds heard so often they have several takes (not the weapons' shots: one each, to tell them apart by ear): one is picked at random, never the same twice in a row. */
const TAKES: Partial<Record<SoundName, readonly SoundName[]>> = {
  ...threeTakes('jump', ['springy', 'heavy', 'winged', 'squishy', 'fluffy']),
  ...threeTakes('land', ['springy', 'heavy', 'winged', 'squishy', 'fluffy']),
  step_grass: ['step_grass', 'step_grass_2'],
  step_sand: ['step_sand', 'step_sand_2'],
  step_wood: ['step_wood', 'step_wood_2'],
  step_snow: ['step_snow', 'step_snow_2'],
  hit_stuffing: ['hit_stuffing', 'hit_stuffing_2', 'hit_stuffing_3'],
  hit_armor: ['hit_armor', 'hit_armor_2', 'hit_armor_3'],
  impact: ['impact', 'impact_2'],
};

/** A plush's voice, by the animal of its head: a yelp when hit, a wail when knocked out, a cheer. */
export type VoiceKind = 'hurt' | 'ko' | 'cheer';
const VOICE_KINDS: readonly VoiceKind[] = ['hurt', 'ko', 'cheer'];
export type VoiceName = `voice_${Animal}_${VoiceKind}`;
type ClipName = SoundName | VoiceName;

/** Beyond this distance (world units) from the listener a sound is silent. */
const HEARING = 28;
/** Distance at which a sound is panned fully to one side. */
const PAN_WIDTH = 16;
const MAX_VOICES = 5;
/** How loud the animal voices are evened out to (their average level, in dB): just under the knockout pop. */
const VOICE_LEVEL = -24;
/** The level (average, dB) a many-take sound's takes are evened out to, so none stands out; and the
 *  pickups'. (The generator makes them anywhere from soft to loud.) */
const TAKE_LEVEL = -20;
const PICKUP_LEVEL = -24;
const TAKEN = new Set<string>(Object.values(TAKES).flat());
/** Footsteps are evened out well below everything else: felt more than heard. */
const STEP_LEVEL = -32;
/** Single sounds evened out to a level of their own: the chests' openings (the royal chest's a little
 *  grander), a few that came out far louder or softer than the rest, the confirms, the weapons. */
const LEVEL: Partial<Record<SoundName, number>> = {
  chest_open_low: -23, chest_open: -22, chest_open_food: -22, chest_open_high: -19,
  lose: -18, strike_whistle: -19, train_toot: -20, plow_horn: -19, ship_bell: -20, cannon_fire: -19,
  armor_up: -22, dig_scrape: -23, swap: -23, splash: -25,
  // Pirate Cove: the parrot and the current over the fight, the sea and gulls well under it.
  parrot_squawk: -22, current_whoosh: -24, shark_warning: -21, gull_cry: -31, sea_waves: -31, waterfall_rush: -28,
  // The Rinse starting to rise: a toy alarm bell, a signal like the ship's bell, a little under it.
  rinse_rising: -22,
  hit_confirm: -26, ko_confirm: -21,
  // Using an item: under the fight while it lasts, then a clear finish.
  use_puff: -26, use_sewing: -26, use_juice: -26, use_bag: -26, use_cardboard: -26,
  heal_small: -24, heal: -22, heal_big: -19, juice_done: -22,
  // Each weapon has one shot sound of its own (so you can tell what's firing), evened out like the rest.
  cork_pop: -20, dart_shot: -20, soaker_shot: -20, band_twang: -20, marble_shot: -20, pillow_swing: -20, glitter_throw: -20, bubble_blow: -20,
};

/** What a clip is evened out to, if it is. */
function levelOf(name: string): number | undefined {
  if (name.startsWith('voice_')) return VOICE_LEVEL;
  if (name.startsWith('part_') || name.startsWith('grab_')) return PICKUP_LEVEL;
  if (name.startsWith('step_')) return STEP_LEVEL;
  return TAKEN.has(name) ? TAKE_LEVEL : LEVEL[name as SoundName];
}
const MUTE_KEY = 'stuffed.muted';
const NOTHING = () => {};

export interface PlayOptions {
  /** World position; omitted = non-positional (UI, announcements). */
  at?: Vec2;
  volume?: number;
  /** Random pitch spread, e.g. 0.1 = ±5%. */
  pitchSpread?: number;
}

export class Sound {
  /** Where the camera is; positional sounds are heard from here. */
  readonly listener: Vec2 = { x: 0, y: 0 };
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private readonly buffers = new Map<ClipName, AudioBuffer>();
  private readonly voices = new Map<ClipName, number>();
  /** Gain that evens out a clip (they come out of the generator anywhere from soft to loud). */
  private readonly levels = new Map<ClipName, number>();
  /** The take of each many-take sound played last. */
  private readonly lastTake = new Map<SoundName, SoundName>();
  /** Animals whose voices are loaded (or asked for before audio started). */
  private readonly animals = new Set<Animal>();
  private muted = false;
  /** Looping clips, made seamless once. */
  private readonly loops = new Map<ClipName, AudioBuffer>();

  constructor(private readonly baseUrl: string) {
    try {
      this.muted = localStorage.getItem(MUTE_KEY) === '1';
    } catch {
      // storage blocked: start unmuted
    }
    // Browsers only allow audio after a user gesture.
    const unlock = () => {
      this.start();
      window.removeEventListener('pointerdown', unlock);
      window.removeEventListener('keydown', unlock);
    };
    window.addEventListener('pointerdown', unlock);
    window.addEventListener('keydown', unlock);
  }

  get isMuted(): boolean {
    return this.muted;
  }

  /** The audio context and the master volume (for the music), once audio has started. */
  get output(): { ctx: AudioContext; master: GainNode } | null {
    return this.ctx && this.master ? { ctx: this.ctx, master: this.master } : null;
  }

  /** Called once audio may play (after the first tap or key). */
  onStart: (() => void) | null = null;

  toggleMute(): boolean {
    this.muted = !this.muted;
    if (this.master) this.master.gain.value = this.muted ? 0 : 1;
    try {
      localStorage.setItem(MUTE_KEY, this.muted ? '1' : '0');
    } catch {
      // not persisted; fine
    }
    return this.muted;
  }

  /** Plays a sound; the returned function fades it out early (a no-op once it has ended). */
  play(name: ClipName, { at, volume = 1, pitchSpread = 0.1 }: PlayOptions = {}): () => void {
    const takes = TAKES[name as SoundName]?.filter((t) => this.buffers.has(t) && t !== this.lastTake.get(name as SoundName));
    if (takes?.length) {
      const take = takes[Math.floor(Math.random() * takes.length)]!;
      this.lastTake.set(name as SoundName, take);
      name = take;
    }
    const ctx = this.ctx;
    const buffer = this.buffers.get(name);
    if (!ctx || !this.master || !buffer || this.muted) return NOTHING;

    let gain = volume * (this.levels.get(name) ?? 1);
    let pan = 0;
    if (at) {
      const dx = at.x - this.listener.x;
      const dy = at.y - this.listener.y;
      const d = Math.hypot(dx, dy);
      if (d >= HEARING) return NOTHING;
      gain *= (1 - d / HEARING) ** 1.6;
      pan = Math.max(-1, Math.min(1, dx / PAN_WIDTH));
    }
    if (gain < 0.02) return NOTHING;
    const playing = this.voices.get(name) ?? 0;
    if (playing >= MAX_VOICES) return NOTHING;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.playbackRate.value = 1 + (Math.random() - 0.5) * pitchSpread;
    const g = ctx.createGain();
    g.gain.value = gain;
    const p = ctx.createStereoPanner();
    p.pan.value = pan;
    source.connect(g).connect(p).connect(this.master);
    this.voices.set(name, playing + 1);
    let ended = false;
    source.onended = () => {
      ended = true;
      this.voices.set(name, Math.max(0, (this.voices.get(name) ?? 1) - 1));
    };
    source.start();
    return () => {
      if (ended) return;
      const now = ctx.currentTime;
      g.gain.setValueAtTime(g.gain.value, now);
      g.gain.linearRampToValueAtTime(0, now + 0.08);
      source.stop(now + 0.1);
    };
  }

  /**
   * Plays a clip round and round (a place's background sound: waves, a waterfall), seamless, at
   * `volume` (changed as you move, with `set`); `stop` fades it out. Null until the clip has loaded
   * (try again later).
   */
  loop(name: SoundName, volume: number): { set: (volume: number) => void; stop: () => void } | null {
    const ctx = this.ctx;
    const clip = this.buffers.get(name);
    if (!ctx || !this.master || !clip) return null;
    let buffer = this.loops.get(name);
    if (!buffer) this.loops.set(name, (buffer = seamless(ctx, clip, Math.min(2, clip.duration / 4))));
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.loop = true;
    const level = this.levels.get(name) ?? 1;
    const g = ctx.createGain();
    g.gain.value = 0;
    source.connect(g).connect(this.master);
    source.start();
    const set = (v: number) => g.gain.setTargetAtTime(v * level, ctx.currentTime, 0.3);
    set(volume);
    return {
      set,
      stop: () => {
        g.gain.setTargetAtTime(0, ctx.currentTime, 0.3);
        source.stop(ctx.currentTime + 1.5);
      },
    };
  }

  private start(): void {
    if (this.ctx) return;
    this.ctx = new AudioContext();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 1;
    this.master.connect(this.ctx.destination);
    void this.ctx.resume();
    // Quiet in a background tab (the music loops).
    document.addEventListener('visibilitychange', () => void (document.hidden ? this.ctx?.suspend() : this.ctx?.resume()));
    for (const name of SOUNDS) void this.load(name);
    for (const animal of this.animals) this.loadVoice(animal);
    this.onStart?.();
  }

  /** Gets an animal's voice clips ready (once). */
  needVoice(animal: Animal): void {
    if (this.animals.has(animal)) return;
    this.animals.add(animal);
    if (this.ctx) this.loadVoice(animal);
  }

  private loadVoice(animal: Animal): void {
    for (const kind of VOICE_KINDS) void this.load(`voice_${animal}_${kind}`);
  }

  private async load(name: ClipName): Promise<void> {
    try {
      const res = await fetch(`${this.baseUrl}sfx/${name}.mp3`);
      if (!res.ok) return;
      const buffer = await this.ctx!.decodeAudioData(await res.arrayBuffer());
      const level = levelOf(name);
      if (level !== undefined) this.levels.set(name, evenOut(buffer, level));
      this.buffers.set(name, buffer);
    } catch {
      // a missing or broken file just stays silent
    }
  }
}

/** The gain that brings a clip's average level to `level` dB (within reason, and never past its
 *  peaks' headroom: clicky clips with sharp peaks would distort first). */
function evenOut(buffer: AudioBuffer, level: number): number {
  const data = buffer.getChannelData(0);
  let sum = 0;
  let peak = 0;
  for (let i = 0; i < data.length; i++) {
    sum += data[i]! * data[i]!;
    peak = Math.max(peak, Math.abs(data[i]!));
  }
  const db = 10 * Math.log10(sum / Math.max(1, data.length) + 1e-12);
  return Math.min(2, 0.9 / Math.max(peak, 1e-6), Math.max(0.15, 10 ** ((level - db) / 20)));
}

/** A clip made to loop without a seam (the music): its end crossfaded into its start (a little shorter for it). */
export function seamless(ctx: BaseAudioContext, clip: AudioBuffer, seconds = 2): AudioBuffer {
  const fade = Math.min(Math.floor(seconds * clip.sampleRate), Math.floor(clip.length / 3));
  const out = ctx.createBuffer(clip.numberOfChannels, clip.length - fade, clip.sampleRate);
  for (let c = 0; c < clip.numberOfChannels; c++) {
    const src = clip.getChannelData(c);
    const dst = out.getChannelData(c);
    dst.set(src.subarray(fade, clip.length - fade), fade);
    // The start fades in over the last `fade` samples fading out (equal power), so the loop runs on.
    for (let i = 0; i < fade; i++) {
      const t = i / fade;
      dst[i] = src[i]! * Math.sqrt(t) + src[clip.length - fade + i]! * Math.sqrt(1 - t);
    }
  }
  return out;
}
